    private Double totalSpent;
    private Double averageBudget;

    public UserTripSummaryDTO() {
    }

    public UserTripSummaryDTO(Long userId, String name, Long totalTrips, Long completedTrips,
                              Long cancelledTrips, Double totalSpent, Double averageBudget) {
        this.userId = userId;
        this.name = name;
        this.totalTrips = totalTrips;
        this.completedTrips = completedTrips;
        this.cancelledTrips = cancelledTrips;
        this.totalSpent = totalSpent;
        this.averageBudget = averageBudget;
    }

    public static Builder builder() {
        return new Builder();
    }

    public static class Builder {
        private Long userId;
        private String name;
        private Long totalTrips;
        private Long completedTrips;
        private Long cancelledTrips;
        private Double totalSpent;
        private Double averageBudget;

        public Builder userId(Long userId) {
            this.userId = userId;
            return this;
        }

        public Builder name(String name) {
            this.name = name;
            return this;
        }

        public Builder totalTrips(Long totalTrips) {
            this.totalTrips = totalTrips;
            return this;
        }

        public Builder completedTrips(Long completedTrips) {
            this.completedTrips = completedTrips;
            return this;
        }

        public Builder cancelledTrips(Long cancelledTrips) {
            this.cancelledTrips = cancelledTrips;
            return this;
        }

        public Builder totalSpent(Double totalSpent) {
            this.totalSpent = totalSpent;
            return this;
        }

        public Builder averageBudget(Double averageBudget) {
            this.averageBudget = averageBudget;
            return this;
        }

        public UserTripSummaryDTO build() {
            return new UserTripSummaryDTO(userId, name, totalTrips, completedTrips, cancelledTrips, totalSpent, averageBudget);
        }
    }

    public Long getUserId() {
        return userId;
    }

    public void setUserId(Long userId) {
        this.userId = userId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public Long getTotalTrips() {
        return totalTrips;
    }

    public void setTotalTrips(Long totalTrips) {
        this.totalTrips = totalTrips;
    }

    public Long getCompletedTrips() {
        return completedTrips;
    }

    public void setCompletedTrips(Long completedTrips) {
        this.completedTrips = completedTrips;
    }

    public Long getCancelledTrips() {
        return cancelledTrips;
    }

    public void setCancelledTrips(Long cancelledTrips) {
        this.cancelledTrips = cancelledTrips;
    }

    public Double getTotalSpent() {
        return totalSpent;
    }

    public void setTotalSpent(Double totalSpent) {
        this.totalSpent = totalSpent;
    }

    public Double getAverageBudget() {
        return averageBudget;
    }

    public void setAverageBudget(Double averageBudget) {
        this.averageBudget = averageBudget;
    }
}

package com.team15.tripplanning.userservice;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.team15.tripplanning.userservice.dto.TopTravelerDTO;
import com.team15.tripplanning.userservice.dto.UserProfileDTO;
import com.team15.tripplanning.userservice.dto.UserTripSummaryDTO;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import org.junit.jupiter.api.Test;

class UserDtoBuilderContractTest {

    @Test
    void m1UserDtosExposeBuilderContracts() throws Exception {
        assertBuilderContract(UserTripSummaryDTO.class, Map.of(
                "userId", 1L,
                "name", "Alice",
                "totalTrips", 12L,
                "completedTrips", 9L,
                "cancelledTrips", 3L,
                "totalSpent", 2440.4d,
                "averageBudget", 203.3d
        ));

        assertBuilderContract(TopTravelerDTO.class, Map.of(
                "userId", 2L,
                "name", "Bob",
                "totalSpent", 1800.0d,
                "tripCount", 7L
        ));

        Map<String, Object> preferences = new HashMap<>();
        preferences.put("travelStyle", "ADVENTURE");

        assertBuilderContract(UserProfileDTO.class, Map.of(
                "userId", 3L,
                "name", "Carol",
                "email", "carol@example.com",
                "phone", "+1000000",
                "preferences", preferences,
                "savedDestinations", new ArrayList<>(),
                "totalSavedDestinations", 0L
        ));
    }

    private static void assertBuilderContract(Class<?> dtoClass, Map<String, Object> fieldValues) throws Exception {
        Method builderMethod = dtoClass.getDeclaredMethod("builder");
        assertTrue(Modifier.isPublic(builderMethod.getModifiers()));
        assertTrue(Modifier.isStatic(builderMethod.getModifiers()));

        Object builder = builderMethod.invoke(null);
        Class<?> builderClass = builder.getClass();

        for (Map.Entry<String, Object> entry : fieldValues.entrySet()) {
            Method setter = builderClass.getMethod(entry.getKey(), dtoClass.getDeclaredField(entry.getKey()).getType());
            assertEquals(builderClass, setter.getReturnType());
            setter.invoke(builder, entry.getValue());
        }

        Method build = builderClass.getMethod("build");
        Object built = build.invoke(builder);
        assertEquals(dtoClass, built.getClass());
    }
}

package com.team15.tripplanning.userservice;

import static org.hamcrest.Matchers.is;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.team15.tripplanning.userservice.controller.UserController;
import com.team15.tripplanning.userservice.dto.UserTripSummaryDTO;
import com.team15.tripplanning.userservice.service.SavedDestinationService;
import com.team15.tripplanning.userservice.service.UserService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;

class UserTripSummaryEndpointIntegrationTest {

    private MockMvc mockMvc;
    private UserService userService;

    @BeforeEach
    void setUp() {
        userService = Mockito.mock(UserService.class);
        SavedDestinationService savedDestinationService = Mockito.mock(SavedDestinationService.class);
        mockMvc = MockMvcBuilders.standaloneSetup(new UserController(userService, savedDestinationService)).build();
    }

    @Test
    void tripSummaryEndpointReturnsExpectedFields() throws Exception {
        UserTripSummaryDTO dto = UserTripSummaryDTO.builder()
                .userId(15L)
                .name("Nora")
                .totalTrips(10L)
                .completedTrips(7L)
                .cancelledTrips(3L)
                .totalSpent(1550.0)
                .averageBudget(155.0)
                .build();

        when(userService.getTripSummary(15L)).thenReturn(dto);

        mockMvc.perform(get("/api/users/15/trip-summary"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.userId", is(15)))
                .andExpect(jsonPath("$.name", is("Nora")))
                .andExpect(jsonPath("$.totalTrips", is(10)))
                .andExpect(jsonPath("$.completedTrips", is(7)))
                .andExpect(jsonPath("$.cancelledTrips", is(3)))
                .andExpect(jsonPath("$.totalSpent", is(1550.0)))
                .andExpect(jsonPath("$.averageBudget", is(155.0)));
    }
}
